df.sample(10)

"""### size ofthe data frame"""

df.shape

"""### basic information of the dataset"""

df.info()

"""### checking sex column"""

df['Sex'].value_counts()

"""### checking null value"""

df.isnull().sum()

df.describe()

"""# CLEANING

### FILL EMPTY AGE WITH THE MEDAIN AGE
"""

df['Age']=df['Age'].fillna(df['Age'].median())

"""# FILLING EMBARKED column with the most occur value"""

df['Embarked']=df['Embarked'].fillna(df['Embarked'].mode()[0])

df['Age'].median()

df

"""## add a column has_cabin to show which has cabin or not from cabin_no"""

df['has_Cabin']= df['Cabin'].notna().astype(int)
df.drop('Cabin',axis=1,inplace=True)

"""### show df after some cleaning"""

df.describe()

